50	// modify it under the terms of the GNU General Public License as published
51	// by the Free Software Foundation, either version 3 of the License, or (at
52	// your option) any later version.
53	//
54	// This program is distributed in the hope that it will be useful, but WITHOUT
55	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
56	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
57	// for more details.
58	//
59	// You should have received a copy of the GNU General Public License along
60	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
61	// target there if the PDF file isn't present.)  If not, see
62	// <http://www.gnu.org/licenses/> for a copy.
63	// }}}
64	// License:	GPL, v3, as defined and found on www.gnu.org,
65	// {{{
66	//		http://www.gnu.org/licenses/gpl.html
67	//
68	////////////////////////////////////////////////////////////////////////////////
69	//
70	`default_nettype	none
71	// }}}
72	module	wbdblpriarb #(
73			// {{{
74			parameter	DW=32, AW=32,
75			// OPT_ZERO_ON_IDLE
76			// {{{
77			// OPT_ZERO_ON_IDLE uses more logic than the alternative.  It
78			// should be useful for reducing power, as these circuits tend
79			// to drive wires all the way across the design, but it may also
80			// slow down the master clock.  I've used it as an option when
81			// using VER1LATOR, 'cause zeroing things on idle can make them
82			// stand out all the more when staring at wires and dumps and
83			// such.
84			parameter	[0:0]		OPT_ZERO_ON_IDLE = 1'b0
85			// }}}
86	`ifdef FORMAL
87			// Parameters used in the formal proof only
88			, parameter	F_LGDEPTH = 3,
89			parameter	F_MAX_STALL = 0,
90			parameter	F_MAX_ACK_DELAY=0
91	`endif
92			// }}}
93		) (
94			// {{{
95			input	wire			i_clk, i_reset,
96			// Bus A
97			// {{{
98			input	wire			i_a_cyc_a, i_a_cyc_b,
99							i_a_stb_a, i_a_stb_b, i_a_we,
100			input	wire	[(AW-1):0]	i_a_adr,
101			input	wire	[(DW-1):0]	i_a_dat,
102			input	wire	[(DW/8-1):0]	i_a_sel,
103			output	wire			o_a_stall, o_a_ack, o_a_err,
104			// }}}
105			// Bus B
106			// {{{
107			input	wire			i_b_cyc_a, i_b_cyc_b,
108							i_b_stb_a, i_b_stb_b, i_b_we,
109			input	wire	[(AW-1):0]	i_b_adr,
110			input	wire	[(DW-1):0]	i_b_dat,
111			input	wire	[(DW/8-1):0]	i_b_sel,
112			output	wire			o_b_stall, o_b_ack, o_b_err,
113			// }}}
114			// Both buses (i.e. the outgoing, arbitrated bus)
115			// {{{
116			output	wire			o_cyc_a, o_cyc_b,
117							o_stb_a, o_stb_b, o_we,
118			output	wire	[(AW-1):0]	o_adr,
119			output	wire	[(DW-1):0]	o_dat,
120			output	wire	[(DW/8-1):0]	o_sel,
121			input	wire			i_stall, i_ack, i_err
122			// }}}
123	`ifdef	FORMAL
124			// {{{
125			// These wires are relics from when the ZipCPU was verified
126			// with this arbiter internal to it.  Since this is no longer
127			// the case, they're now no more than declarations
128			, output	wire	[(F_LGDEPTH-1):0]
129				f_nreqs_a, f_nacks_a, f_outstanding_a,
130				f_nreqs_b, f_nacks_b, f_outstanding_b,
131				f_a_nreqs_a, f_a_nacks_a, f_a_outstanding_a,
132				f_a_nreqs_b, f_a_nacks_b, f_a_outstanding_b,
133				f_b_nreqs_a, f_b_nacks_a, f_b_outstanding_a,
134				f_b_nreqs_b, f_b_nacks_b, f_b_outstanding_b
135			// }}}
136	`endif
137			// }}}
138		);
139	
140		// r_a_owner
141		// {{{
142		// All of our logic is really captured in the 'r_a_owner' register.
143		// This register determines who owns the bus.  If no one is requesting
144		// the bus, ownership goes to A on the next clock.  Otherwise, if B is
145		// requesting the bus and A is not, then ownership goes to not A on
146		// the next clock.  (Sounds simple ...)
147		//
148		// The CYC logic is here to make certain that, by the time we determine
149		// who the bus owner is, we can do so based upon determined criteria.
150		reg	r_a_owner;
151	
152		initial	r_a_owner = 1'b1;
153		always @(posedge i_clk)
154		if (i_reset)
155			r_a_owner <= 1'b1;
156		/*
157		// Remain with the "last owner" until 1) the other bus requests
158		// access, and 2) the last owner no longer wants it.  This
159		// logic "idles" on the last owner.
160		//
161		// This is an alternating bus owner strategy
162		//
163		else if ((!o_cyc_a)&&(!o_cyc_b))
164			r_a_owner <= ((i_b_stb_a)||(i_b_stb_b))? 1'b0:1'b1;
165		//
166		// Expanding this out
167		//
168		// else if ((r_a_owner)&&((i_a_cyc_a)||(i_a_cyc_b)))
169		//		r_a_owner <= 1'b1;
170		// else if ((!r_a_owner)&&((i_b_cyc_a)||(i_b_cyc_b)))
171		//		r_a_owner <= 1'b0;
172		// else if ((r_a_owner)&&((i_b_stb_a)||(i_b_stb_b)))
173		//		r_a_owner <= 1'b0;
174		// else if ((!r_a_owner)&&((i_a_stb_a)||(i_a_stb_b)))
175		//		r_a_owner <= 1'b0;
176		//
177		// Logic required:
178		//
179		//	Reset line
180		//	+ 9 inputs (data)
181		//	+ 9 inputs (CE)
182		//	Could be done with three LUTs
183		//		First two evaluate o_cyc_a and o_cyc_b (above)
184		*/
185		// Option 2:
186		//
187		// "Idle" on A as the owner.
188		// If a request is made from B, AND A is idle, THEN
189		// switch.  Otherwise, if B is ever idle, revert back to A
190		// regardless of whether A wants it or not.
191		else if ((!i_b_cyc_a)&&(!i_b_cyc_b))
192			r_a_owner <= 1'b1;
193		else if ((!i_a_cyc_a)&&(!i_a_cyc_b)
194				&&((i_b_stb_a)||(i_b_stb_b)))
195			r_a_owner <= 1'b0;
196		// }}}
197	
198		// o_cyc*, o_stb*, o_we
199		// {{{
200		// Realistically, if neither master owns the bus, the output is a
201		// don't care.  Thus we trigger off whether or not 'A' owns the bus.
202		// If 'B' owns it all we care is that 'A' does not.  Likewise, if
203		// neither owns the bus than the values on these various lines are
204		// irrelevant.
205	
206		assign o_cyc_a = ((r_a_owner) ? i_a_cyc_a : i_b_cyc_a);
207		assign o_cyc_b = ((r_a_owner) ? i_a_cyc_b : i_b_cyc_b);
208		assign o_stb_a = (r_a_owner) ? i_a_stb_a : i_b_stb_a;
209		assign o_stb_b = (r_a_owner) ? i_a_stb_b : i_b_stb_b;
210		assign o_we    = (r_a_owner) ? i_a_we    : i_b_we;
211		// }}}
212	
213		// Other bus outputs and returns
214		// {{{
215		generate if (OPT_ZERO_ON_IDLE)
216		begin : OPT_LOWPOWER
217			// {{{
218			wire	o_cyc, o_stb;
219	
220			assign	o_cyc     = ((o_cyc_a)||(o_cyc_b));
221			assign	o_stb     = ((o_stb_a)||(o_stb_b));
222			assign	o_adr     = (o_stb)?((r_a_owner) ? i_a_adr  : i_b_adr):0;
223			assign	o_dat     = (o_stb)?((r_a_owner) ? i_a_dat  : i_b_dat):0;
224			assign	o_sel     = (o_stb)?((r_a_owner) ? i_a_sel  : i_b_sel):0;
225			assign	o_a_ack   = (o_cyc)&&( r_a_owner) ? i_ack   : 1'b0;
226			assign	o_b_ack   = (o_cyc)&&(!r_a_owner) ? i_ack   : 1'b0;
227			assign	o_a_stall = (o_cyc)&&( r_a_owner) ? i_stall : 1'b1;
228			assign	o_b_stall = (o_cyc)&&(!r_a_owner) ? i_stall : 1'b1;
229			assign	o_a_err   = (o_cyc)&&( r_a_owner) ? i_err : 1'b0;
230			assign	o_b_err   = (o_cyc)&&(!r_a_owner) ? i_err : 1'b0;
231			// }}}
232		end else begin : OPT_LOWLOGIC
233			// {{{
234			assign o_adr   = (r_a_owner) ? i_a_adr   : i_b_adr;
235			assign o_dat   = (r_a_owner) ? i_a_dat   : i_b_dat;
236			assign o_sel   = (r_a_owner) ? i_a_sel   : i_b_sel;
237	
238			// We cannot allow the return acknowledgement to ever go high if
239			// the master in question does not own the bus.  Hence we force it
240			// low if the particular master doesn't own the bus.
241			assign	o_a_ack   = ( r_a_owner) ? i_ack   : 1'b0;
242			assign	o_b_ack   = (!r_a_owner) ? i_ack   : 1'b0;
243	
244			// Stall must be asserted on the same cycle the input master asserts
245			// the bus, if the bus isn't granted to him.
246			assign	o_a_stall = ( r_a_owner) ? i_stall : 1'b1;
247			assign	o_b_stall = (!r_a_owner) ? i_stall : 1'b1;
248	
249			//
250			//
251			assign	o_a_err = ( r_a_owner) ? i_err : 1'b0;
252			assign	o_b_err = (!r_a_owner) ? i_err : 1'b0;
253			// }}}
254		end endgenerate
255		// }}}
256	////////////////////////////////////////////////////////////////////////////////
257	////////////////////////////////////////////////////////////////////////////////
258	////////////////////////////////////////////////////////////////////////////////
259	//
260	// Formal properties
261	// {{{
262	////////////////////////////////////////////////////////////////////////////////
263	////////////////////////////////////////////////////////////////////////////////
264	////////////////////////////////////////////////////////////////////////////////
265	`ifdef	FORMAL
266	`define	ASSERT	assert
267	`ifdef	WBDBLPRIARB
268	`define	ASSUME	assume
269	`else
270	`define	ASSUME	assert
271	`endif
272	
273		reg	f_past_valid;
274		initial	f_past_valid = 1'b0;
275		always @(posedge i_clk)
276			f_past_valid <= 1'b1;
277	
278		initial	`ASSUME(i_reset);
279		always @(*)
280		if (!f_past_valid)
281			`ASSUME(i_reset);
282	
283		initial	`ASSUME(!i_a_cyc_a);
284		initial	`ASSUME(!i_a_stb_a);
285		initial	`ASSUME(!i_a_cyc_b);
286		initial	`ASSUME(!i_a_stb_b);
287	
288		initial	`ASSUME(!i_b_cyc_a);
289		initial	`ASSUME(!i_b_stb_a);
290		initial	`ASSUME(!i_b_cyc_b);
291		initial	`ASSUME(!i_b_stb_b);
292	
293		initial	`ASSUME(!i_ack);
294		initial	`ASSUME(!i_err);
295	
296		always @(*)
297			`ASSUME((!i_a_cyc_a)||(!i_a_cyc_b));
298		always @(*)
299			`ASSUME((!i_b_cyc_a)||(!i_b_cyc_b));
300	
301		always @(posedge i_clk)
302		if ((f_past_valid)&&($past(i_a_cyc_a)))
303			`ASSUME(!i_a_cyc_b);
304	
305		always @(posedge i_clk)
306		if ((f_past_valid)&&($past(i_a_cyc_b)))
307			`ASSUME(!i_a_cyc_a);
308	
309		always @(posedge i_clk)
310		if ((f_past_valid)&&($past(i_b_cyc_a)))
311			`ASSUME(!i_b_cyc_b);
312	
313		always @(posedge i_clk)
314		if ((f_past_valid)&&($past(i_b_cyc_b)))
315			`ASSUME(!i_b_cyc_a);
316	
317		wire	f_cyc, f_stb;
318		assign	f_cyc = (o_cyc_a)||(o_cyc_b);
319		assign	f_stb = (o_stb_a)||(o_stb_b);
320		always @(posedge i_clk)
321		begin
322			if (o_cyc_a)
323				`ASSERT((i_a_cyc_a)||(i_b_cyc_a));
324			if (o_cyc_b)
325				`ASSERT((i_a_cyc_b)||(i_b_cyc_b));
326			`ASSERT((!o_cyc_a)||(!o_cyc_b));
327		end
328	
329		always @(posedge i_clk)
330		if ((f_past_valid)&&(!$past(i_reset)))
331		begin
332			if ($past(f_cyc))
333			begin
334				if (($past(o_cyc_a))&&(o_cyc_a))
335					`ASSERT($past(r_a_owner) == r_a_owner);
336				if (($past(o_cyc_b))&&(o_cyc_b))
337					`ASSERT($past(r_a_owner) == r_a_owner);
338			end else begin
339				if (($past(i_a_stb_a))||($past(i_a_stb_b)))
340					`ASSERT(r_a_owner);
341				if (($past(i_b_stb_a))||($past(i_b_stb_b)))
342					`ASSERT(!r_a_owner);
343			end
344		end
345	
346	
347		fwb_master #(
348			// {{{
349			.AW(AW), .DW(DW),
350				.F_MAX_STALL(F_MAX_STALL),
351				.F_LGDEPTH(F_LGDEPTH),
352				.F_MAX_ACK_DELAY(F_MAX_ACK_DELAY),
353				.F_OPT_RMW_BUS_OPTION(1),
354				.F_OPT_DISCONTINUOUS(1)
355			// }}}
356		) f_wbm_a (
357			// {{{
358			i_clk, i_reset,
359				o_cyc_a, o_stb_a, o_we, o_adr, o_dat, o_sel,
360				(o_cyc_a)&&(i_ack), i_stall, 32'h0, (o_cyc_a)&&(i_err),
361				f_nreqs_a, f_nacks_a, f_outstanding_a
362			// }}}
363		);
364	
365	
366		fwb_master #(
367			// {{{
368			.AW(AW), .DW(DW),
369				.F_MAX_STALL(F_MAX_STALL),
370				.F_MAX_ACK_DELAY(F_MAX_ACK_DELAY),
371				.F_LGDEPTH(F_LGDEPTH),
372				.F_OPT_RMW_BUS_OPTION(1),
373				.F_OPT_DISCONTINUOUS(1)
374			// }}}
375		) f_wbm_b(
376			// {{{
377			i_clk, i_reset,
378				o_cyc_b, o_stb_b, o_we, o_adr, o_dat, o_sel,
379				(o_cyc_b)&&(i_ack), i_stall, 32'h0, (o_cyc_b)&&(i_err),
380				f_nreqs_b, f_nacks_b, f_outstanding_b
381			// }}}
382		);
383	
384	`ifdef	WBDBLPRIARB
385	`define	F_SLAVE	fwb_slave
386	`else
387	`define	F_SLAVE	fwb_counter
388	`endif
389	
390		`F_SLAVE  #(
391			// {{{
392			.AW(AW), .DW(DW), .F_MAX_STALL(0),
393				.F_LGDEPTH(F_LGDEPTH),
394				.F_MAX_ACK_DELAY(0),
395				.F_OPT_RMW_BUS_OPTION(1),
396				.F_OPT_DISCONTINUOUS(1)
397			// }}}
398		) f_wba_a(
399			// {{{
400			i_clk, i_reset,
401				i_a_cyc_a, i_a_stb_a, i_a_we, i_a_adr, i_a_dat, i_a_sel,
402				(o_cyc_a)&&(o_a_ack), o_a_stall, 32'h0, (o_cyc_a)&&(o_a_err),
403				f_a_nreqs_a, f_a_nacks_a, f_a_outstanding_a
404			// }}}
405		);
406	
407		`F_SLAVE  #(
408			// {{{
409			.AW(AW), .DW(DW), .F_MAX_STALL(0),
410				.F_LGDEPTH(F_LGDEPTH),
411				.F_MAX_ACK_DELAY(0),
412				.F_OPT_RMW_BUS_OPTION(1),
413				.F_OPT_DISCONTINUOUS(1)
414			// }}}
415		) f_wba_b(
416			// {{{
417			i_clk, i_reset,
418				i_a_cyc_b, i_a_stb_b, i_a_we, i_a_adr, i_a_dat, i_a_sel,
419				(o_cyc_b)&&(o_a_ack), o_a_stall, 32'h0, (o_cyc_b)&&(o_a_err),
420				f_a_nreqs_b, f_a_nacks_b, f_a_outstanding_b
421			// }}}
422		);
423	
424		`F_SLAVE  #(
425			// {{{
426			.AW(AW), .DW(DW), .F_MAX_STALL(0),
427				.F_LGDEPTH(F_LGDEPTH),
428				.F_MAX_ACK_DELAY(0),
429				.F_OPT_RMW_BUS_OPTION(1),
430				.F_OPT_DISCONTINUOUS(1)
431			// }}}
432		) f_wbb_a(
433			// {{{
434			i_clk, i_reset,
435				i_b_cyc_a, i_b_stb_a, i_b_we, i_b_adr, i_b_dat, i_b_sel,
436				(o_cyc_a)&&(o_b_ack), o_b_stall, 32'h0, (o_cyc_a)&&(o_b_err),
437				f_b_nreqs_a, f_b_nacks_a, f_b_outstanding_a
438			// }}}
439		);
440	
441		`F_SLAVE  #(
442			// {{{
443			.AW(AW), .DW(DW), .F_MAX_STALL(0),
444				.F_LGDEPTH(F_LGDEPTH),
445				.F_MAX_ACK_DELAY(0),
446				.F_OPT_RMW_BUS_OPTION(1),
447				.F_OPT_DISCONTINUOUS(1)
448			// }}}
449		) f_wbb_b(
450			// {{{
451			i_clk, i_reset,
452				i_b_cyc_b, i_b_stb_b, i_b_we, i_b_adr, i_b_dat, i_b_sel,
453				(o_cyc_b)&&(o_b_ack), o_b_stall, 32'h0, (o_cyc_b)&&(o_b_err),
454				f_b_nreqs_b, f_b_nacks_b, f_b_outstanding_b
455			// }}}
456		);
457	
458		// Induction properties, relating nreqs and nacks to r_a_owner
459		// {{{
460		always @(posedge i_clk)
461		if ((f_past_valid)&&(!$past(i_reset)))
462		begin
463			if (r_a_owner)
464			begin : A_IS_OWNER
465				// {{{
466				`ASSERT(f_b_nreqs_a == 0);
467				`ASSERT(f_b_nreqs_b == 0);
468				//
469				`ASSERT(f_b_nacks_a == 0);
470				`ASSERT(f_b_nacks_b == 0);
471				//
472				if (i_a_cyc_a)
473				begin
474					`ASSERT(f_a_outstanding_a == f_outstanding_a);
475					`ASSERT(f_a_outstanding_b == 0);
476					`ASSERT(f_outstanding_b == 0);
477					`ASSERT(f_a_nreqs_b == 0);
478					`ASSERT(f_a_nacks_b == 0);
479				end else if (i_a_cyc_b)
480				begin
481					`ASSERT(f_a_outstanding_b == f_outstanding_b);
482					`ASSERT(f_a_outstanding_a == 0);
483					`ASSERT(f_outstanding_a == 0);
484					`ASSERT(f_a_nreqs_a == 0);
485					`ASSERT(f_a_nacks_a == 0);
486				end
487				// }}}
488			end else begin : B_IS_OWNER
489				// {{{
490				`ASSERT(f_a_nreqs_a == 0);
491				`ASSERT(f_a_nreqs_b == 0);
492				//
493				`ASSERT(f_a_nacks_a == 0);
494				`ASSERT(f_a_nacks_b == 0);
495				//
496				if (i_b_cyc_a)
497				begin
498					`ASSERT(f_b_outstanding_a == f_outstanding_a);
499					`ASSERT(f_b_outstanding_b == 0);
500					`ASSERT(f_outstanding_b == 0);
501					`ASSERT(f_b_nreqs_b == 0);
502					`ASSERT(f_b_nacks_b == 0);
503				end else if (i_b_cyc_b)
504				begin
505					`ASSERT(f_b_outstanding_b == f_outstanding_b);
506					`ASSERT(f_b_outstanding_a == 0);
507					`ASSERT(f_outstanding_a == 0);
508					`ASSERT(f_b_nreqs_a == 0);
509					`ASSERT(f_b_nacks_a == 0);
510				end
511				// }}}
512			end
513		end
514		// }}}
515	
516		always @(posedge i_clk)
517		if ((r_a_owner)&&(i_b_cyc_a))
518			`ASSUME((i_b_stb_a)&&(!i_b_stb_b));
519	
520		always @(posedge i_clk)
521		if ((r_a_owner)&&(i_b_cyc_b))
522			`ASSUME((i_b_stb_b)&&(!i_b_stb_a));
523	
524		always @(posedge i_clk)
525		if ((!r_a_owner)&&(i_a_cyc_a))
526			`ASSUME((i_a_stb_a)&&(!i_a_stb_b));
527	
528		always @(posedge i_clk)
529		if ((!r_a_owner)&&(i_a_cyc_b))
530			`ASSUME((i_a_stb_b)&&(!i_a_stb_a));
531	
532	`endif
533	// }}}
534	endmodule
535	
